from collections import deque


def assign_shifts(shifts, engineers):
    shift_info = {}
    for sid, day, head, mins in shifts:
        shift_info[sid] = (day, head, mins)

    total = sum(h for _, _, h, _ in shifts)
    result = {sid: [] for sid, _, _, _ in shifts}
    if total == 0:
        return result

    to = []
    cap = []
    adj = []

    def new_node():
        adj.append([])
        return len(adj) - 1

    def add_edge(u, v, c):
        idx = len(to)
        to.append(v)
        cap.append(c)
        adj[u].append(idx)
        to.append(u)
        cap.append(0)
        adj[v].append(idx + 1)
        return idx

    src = new_node()
    sink = new_node()

    s_node = {}
    t_node = {}
    for sid, day, head, mins in shifts:
        if head <= 0:
            continue
        s = new_node()
        t = new_node()
        s_node[sid] = s
        t_node[sid] = t
        if mins > 0:
            add_edge(s, sink, mins)
        if head - mins > 0:
            add_edge(s, t, head - mins)
            add_edge(t, sink, head - mins)

    assign_edges = []
    for name in sorted(engineers):
        info = engineers[name]
        mx = info.get("max_shifts", 0)
        if mx <= 0:
            continue
        senior = bool(info.get("senior", False))
        by_day = {}
        for sid in info.get("available", ()):
            if sid in s_node:
                by_day.setdefault(shift_info[sid][0], []).append(sid)
        if not by_day:
            continue
        e = new_node()
        add_edge(src, e, min(mx, len(by_day)))
        for day in sorted(by_day):
            ed = new_node()
            add_edge(e, ed, 1)
            for sid in sorted(by_day[day]):
                target = s_node[sid] if senior else t_node[sid]
                idx = add_edge(ed, target, 1)
                assign_edges.append((idx, name, sid))

    n = len(adj)

    def bfs():
        level = [-1] * n
        level[src] = 0
        q = deque([src])
        while q:
            u = q.popleft()
            for e in adj[u]:
                if cap[e] > 0 and level[to[e]] < 0:
                    level[to[e]] = level[u] + 1
                    q.append(to[e])
        return level

    def dfs(u, f, level, it):
        if u == sink:
            return f
        au = adj[u]
        while it[u] < len(au):
            e = au[it[u]]
            v = to[e]
            if cap[e] > 0 and level[v] == level[u] + 1:
                d = dfs(v, min(f, cap[e]), level, it)
                if d:
                    cap[e] -= d
                    cap[e ^ 1] += d
                    return d
            it[u] += 1
        return 0

    flow = 0
    INF = float("inf")
    while True:
        level = bfs()
        if level[sink] < 0:
            break
        it = [0] * n
        while True:
            f = dfs(src, INF, level, it)
            if not f:
                break
            flow += f

    if flow < total:
        return None

    for idx, name, sid in assign_edges:
        if cap[idx] == 0:
            result[sid].append(name)
    return result
